IV, MX = ('Ivy', MINT), ('Max', SUN)
def bigbtn(icon, t): return f'<div style="height: 68px; border-radius: 22px; background: {PAPER}; border: 2px solid {LINE}; display: flex; align-items: center; gap: 14px; padding: 0 18px; font-size: 21px; font-weight: 700">{ico(icon, 34)}{t}</div>'
def textbox(t, h_=110): return f'<div style="background: {FIELD}; border-radius: 16px; padding: 14px 16px; min-height: {h_}px; font-size: 17px; line-height: 1.35">{t}</div>'
def kv(k, v): return f'<div style="display: flex; justify-content: space-between; padding: 9px 0; border-top: 1px solid {LINE}; font-size: 15px"><span style="color: {MUTED}">{k}</span><b>{v}</b></div>'
def panel(title, *rows): return f'<div style="background: {PAPER}; border-radius: 22px; padding: 12px 16px"><div style="font-size: 16px; font-weight: 800; padding-bottom: 6px">{title}</div>' + ''.join(rows) + '</div>'

