 ('Sticker chart', 'A week at a glance. Lives under the Potty card and on Ollie’s page.', S(nav('Ollie’s stickers', 'Today', ''), h('This week', 26), f'<div style="background: {PAPER}; border-radius: 22px; padding: 12px">{chartrow("MTWTFSS", [["Potty", "Potty"], ["Potty", "Milestone"], ["Potty"], ["Potty", "Play", "Potty"], ["Milestone"], [], []])}</div>', banner('3 more for a shiny one.', MINT, '7 of 10 stickers.'), tab=None)),
 ('Ten stickers', 'Every ten stickers earns a holographic one. It adds up; an accident never takes anything away.', S(fill(), center(f'<div style="width: 230px; height: 230px; border-radius: 50%; background: linear-gradient(135deg, {SKY}, {MINT}, {SUN}, {SHELL}, #C9C3EE); display: flex; align-items: center; justify-content: center">{sticker("Potty", 170)}</div>', h('Ten stickers!', 34, True), p('A shiny one for the sticker book.', 17, INK, 500, True)), fill(), btn('Add to sticker book', 'yellow'), tab=None, bg=PAPER)),
